class Solution:
    def minOperations(self, s: str) -> int:
        count = 0
        count1 = 0
        for i in range(len(s)):
            if i % 2 == 0:
                if s[i] == '1':
                    count += 1
                if s[i] == '0':
                    count1 += 1
            else:
                if s[i] == '0':
                    count += 1
                if s[i] == '1':
                    count1 += 1
        return min(count, count1)

class Solution(object):
    def mergeAlternately(self, word1, word2):
        i=0
        j=0
        st=[]
        while i<len(word1) and j<len(word2):
            st.append(word1[i])
            st.append(word2[j])
            i+=1
            j+=1
        while j<len(word2):
            st.append(word2[j])
            j+=1
        while i<len(word1):
            st.append(word1[i])
            i+=1
        return "".join(st)

